/// Finds the maximum value in a vector of integers.
///
/// # Arguments
///
/// * `numbers` - A slice of integers.
///
/// # Returns
///
/// An `Option<i32>` containing the maximum value if the vector is not empty,
/// or `None` if the vector is empty.
///
/// # Examples
///
/// ```
/// use your_crate_name::find_max; // Replace your_crate_name
///
/// let numbers = vec![1, 5, 2, 8, 3];
/// let max_value = find_max(&numbers);
/// assert_eq!(max_value, Some(8));
///
/// let empty_numbers: Vec<i32> = Vec::new();
/// let max_value_empty = find_max(&empty_numbers);
/// assert_eq!(max_value_empty, None);
/// ```
pub fn find_max(numbers: &[i32]) -> Option<i32> {
    // Handle the empty vector case.
    if numbers.is_empty() {
        return None;
    }

    // Initialize the maximum value with the first element of the vector.
    let mut max_value = numbers[0];

    // Iterate over the remaining elements of the vector.
    for &number in numbers.iter().skip(1) {
        // If the current element is greater than the maximum value, update the maximum value.
        if number > max_value {
            max_value = number;
        }
    }

    // Return the maximum value wrapped in an Option.
    Some(max_value)
}

