// Task represents a task with its properties.
type Task struct {
	ID       int      `json:"id"`
	Title    string   `json:"title"`
	Description string   `json:"description"`
	Completed bool     `json:"completed"`
	CreatedAt time.Time `json:"createdAt"`
}

// TaskService handles task operations.
type TaskService struct {
	tasks []Task
	nextID int
}

// NewTaskService creates a new TaskService instance.
func NewTaskService() *TaskService {
	return &TaskService{
		tasks: []Task{},
		nextID: 1,
	}
}

// GetTasks lists all tasks.
func (s *TaskService) GetTasks() []Task {
	return s.tasks
}

// CreateTask creates a new task.
func (s *TaskService) CreateTask(title string, description string) (Task, error) {
	task := Task{
		ID:       s.nextID,
		Title:    title,
		Description: description,
		Completed: false,
		CreatedAt: time.Now(),
	}
	s.tasks = append(s.tasks, task)
	s.nextID++
	return task, nil
}

// GetTask retrieves a specific task by ID.
func (s *TaskService) GetTask(id int) (Task, error) {
	for _, task := range s.tasks {
		if task.ID == id {
			return task, nil
		}
	}
	return Task{}, fmt.Errorf("task with ID %d not found", id)
}

// UpdateTask updates a task.
func (s *TaskService) UpdateTask(id int, title string, description string, completed bool) error {
	for i, task := range s.tasks {
		if task.ID == id {
			s.tasks[i].Title = title
			s.tasks[i].Description = description
			s.tasks[i].Completed = completed
			return nil
		}
	}
	return fmt.Errorf("task with ID %d not found", id)
}

// DeleteTask deletes a task.
func (s *TaskService) DeleteTask(id int) error {
	for i, task := range s.tasks {
		if task.ID == id {
			s.tasks = append(s.tasks[:i], s.tasks[i+1:]...)
			return nil
		}
	}
	return fmt.Errorf("task with ID %d not found", id)
}

// TaskHandler handles task-related HTTP requests.
